DROP TABLE IF EXISTS `t_collecte`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `t_collecte` (
  `IDCollecte` int(11) NOT NULL AUTO_INCREMENT,
  `IDOuvrage` int(11) DEFAULT NULL,
  `DateSaisie` date DEFAULT NULL,
  `DateRemplissage` date DEFAULT NULL,
  `NomOperateur` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `NomAgentSaisie` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `Service` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `EtatOuvrage` enum('Utilisé','Panne','Abandonné','Détruit','Fonctionnel non encore utilisé','Inachevé') COLLATE utf8_unicode_ci DEFAULT NULL,
  `CodeCauseSiAbandon` enum('Eloignement du PE','Problème sur le forage','Qualité de l''eau','Inondation du PE','Conflit autour du PE','Concurrence d''un PE voisin','Autre') COLLATE utf8_unicode_ci DEFAULT NULL,
  `CauseDestruction` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `PereniteAnneeNbMois` smallint(6) DEFAULT NULL,
  `PereniteAnneeDsJournee` enum('Tarit','Pérenne') COLLATE utf8_unicode_ci DEFAULT NULL,
  `SuperstructureRehabilite` tinyint(1) DEFAULT NULL,
  `EtatMargelle` tinyint(1) DEFAULT NULL,
  `EtancheiteForage` tinyint(1) DEFAULT NULL,
  `EtatFixationPompe` tinyint(1) DEFAULT NULL,
  `EtatAntiBourbier` enum('Pas de dalle anti bourbier','Bon état','Moyen','Mauvais') COLLATE utf8_unicode_ci DEFAULT NULL,
  `EtatCloture` enum('Absente','Existe et fonctionnelle','Existe mais non fonctionnelle') COLLATE utf8_unicode_ci DEFAULT NULL,
  `EtatRigoleEvacuation` enum('Absente','Existe et fonctionnelle','Existe mais non fonctionnelle') COLLATE utf8_unicode_ci DEFAULT NULL,
  `EtatPuitPerdu` enum('Absente','Existe et fonctionnelle','Existe mais non fonctionnelle') COLLATE utf8_unicode_ci DEFAULT NULL,
  `PropreteInterieurCloture` tinyint(1) DEFAULT NULL,
  `PropreteExterieurCloture` tinyint(1) DEFAULT NULL,
  `SourcePollution1` enum('Ruissellement','Pente trop forte','Zone inondable','Epaisseur d''altération faible au voisinage de l''ouvrage','Proximité latrines','Proximité marché','Proximité décharge','Présence de bétail','Etanchéité du forage','Désamorçage fréquent de la pompe') COLLATE utf8_unicode_ci DEFAULT NULL,
  `SourcePollution2` enum('Ruissellement','Pente trop forte','Zone inondable','Epaisseur d''altération faible au voisinage de l''ouvrage','Proximité latrines','Proximité marché','Proximité décharge','Présence de bétail','Etanchéité du forage','Désamorçage fréquent de la pompe') COLLATE utf8_unicode_ci DEFAULT NULL,
  `PresenceDeferiseur` tinyint(1) DEFAULT NULL,
  `DeferiseurUtilise` tinyint(1) DEFAULT NULL,
  `EtatDeferiseur` enum('Bon','Moyen','Mauvais') COLLATE utf8_unicode_ci DEFAULT NULL,
  `NbPompe` smallint(6) DEFAULT NULL,
  `MarquePompe` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `PompeRemplace` tinyint(1) DEFAULT NULL,
  `AnneePosePompe` smallint(6) DEFAULT NULL,
  `FinancementRemplacement` enum('Village','Projet','Privé') COLLATE utf8_unicode_ci DEFAULT NULL,
  `NomProjet` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `EtatPompe` enum('Bon état','Etat moyen','Panne','Inconnu') COLLATE utf8_unicode_ci DEFAULT NULL,
  `DureePanne` enum('Moins de 1 mois','Entre 1 et 6 mois','Entre 6 mois et 1 an','Plus de 1 an','Inconnu') COLLATE utf8_unicode_ci DEFAULT NULL,
  `CauseNonReparation` enum('Manque de pièces','UE non opérationnelle','Entreprise de maintenance non opérationnelle','Coût de la réparation','Autre','Pannes trop fréquentes','Conflits','Captage non exploitable','Coût de l’eau','Qualité de l’eau','Concurrence autres PE','Pollution') COLLATE utf8_unicode_ci DEFAULT NULL,
  `Turbidite` enum('Eau claire','Eau trouble') COLLATE utf8_unicode_ci DEFAULT NULL,
  `OdeurEau` enum('Pas d''odeur','Mauvaise') COLLATE utf8_unicode_ci DEFAULT NULL,
  `GoutEau` enum('Bon','Salé','Mauvais') COLLATE utf8_unicode_ci DEFAULT NULL,
  `PelliculeEnSurface` tinyint(1) DEFAULT NULL,
  `PresenceVers` tinyint(1) DEFAULT NULL,
  `Conductivite` decimal(5,2) DEFAULT NULL,
  `Ph` decimal(5,2) DEFAULT NULL,
  `NitratesNo3` decimal(5,2) DEFAULT NULL,
  `NitritesNo2` decimal(5,2) DEFAULT NULL,
  `FerTotal` decimal(5,2) DEFAULT NULL,
  `ModeGestionOuvrage` enum('Pas de gestion','Gestion communautaire','Gestion déléguée par la communauté','Bienfaiteur','Propriété privée','PE pris en charge par un particulier') COLLATE utf8_unicode_ci DEFAULT NULL,
  `PresenceUniteGestion` tinyint(1) DEFAULT NULL,
  `VillageUE` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `NumVillageUE` varchar(10) COLLATE utf8_unicode_ci DEFAULT NULL,
  `AssistanceBienfaiteur` tinyint(1) DEFAULT NULL,
  `ModePaiementEau` enum('Ni vente, ni cotisation','Vente au volume','Cotisations régulières','Cotisations à la panne') COLLATE utf8_unicode_ci DEFAULT NULL,
  `PrixSeau20Litres` float(8,2) DEFAULT NULL,
  `PrixBassine35Litres` float(8,2) DEFAULT NULL,
  `NomArtisanReparateur` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `VillageResidenceReparateur` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `CahierEntretientPompe` enum('absent','présent bien tenu','présent mal tenu','Inc') COLLATE utf8_unicode_ci DEFAULT NULL,
  `ContratEntretienArtisan` tinyint(1) DEFAULT NULL,
  `TypeContrat` enum('Intervention à la demande','Entretien préventif périodique','Garantie totale','Gestion déléguée du PE','Autre') COLLATE utf8_unicode_ci DEFAULT NULL,
  `Commentaires` text COLLATE utf8_unicode_ci,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `validated` tinyint(1) DEFAULT NULL,
  `validated_at` datetime DEFAULT NULL,
  `NumIRH` varchar(10) COLLATE utf8_unicode_ci DEFAULT NULL,
  `sync` varchar(1) COLLATE utf8_unicode_ci DEFAULT 'N',
  `validated_by` int(11) DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `origin` varchar(2) COLLATE utf8_unicode_ci DEFAULT 'I',
  PRIMARY KEY (`IDCollecte`),
  KEY `IDX_814F5667399640DF` (`IDOuvrage`),
  KEY `IDX_814F5667F54EF1C` (`validated_by`),
  CONSTRAINT `FK_814F5667399640DF` FOREIGN KEY (`IDOuvrage`) REFERENCES `t_ouvrage` (`IDOuvrage`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_814F5667F54EF1C` FOREIGN KEY (`validated_by`) REFERENCES `t_agent` (`IDAgent`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
