DROP TABLE IF EXISTS `t_comite`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `t_comite` (
  `IDComite` int(11) NOT NULL AUTO_INCREMENT,
  `NomComite` varchar(50) DEFAULT NULL,
  `CodeInitComite` varchar(6) DEFAULT NULL,
  `NomSecretaire` varchar(50) CHARACTER SET utf8 DEFAULT NULL,
  `PrenomsSecretaire` varchar(50) CHARACTER SET utf8 DEFAULT NULL,
  `IDNumAppel` int(11) DEFAULT NULL,
  `IDLocalite` int(11) DEFAULT NULL,
  `InitSatus` tinyint(1) DEFAULT '0',
  `deleted_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `sync` varchar(1) DEFAULT 'N',
  `contact` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`IDComite`),
  UNIQUE KEY `CodeInitComite_2` (`CodeInitComite`),
  UNIQUE KEY `IDNumAppel_2` (`IDNumAppel`),
  KEY `IDComite` (`IDComite`),
  KEY `IDNumAppel` (`IDNumAppel`),
  KEY `IDX_F566B2616BD84F81` (`IDLocalite`),
  KEY `CodeInitComite` (`NomComite`),
  CONSTRAINT `FK_F566B26132A52E64` FOREIGN KEY (`IDNumAppel`) REFERENCES `t_numeroappel` (`IDNumAppel`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `FK_F566B2616BD84F81` FOREIGN KEY (`IDLocalite`) REFERENCES `t_localite` (`IDLocalite`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=211 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

