/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`%`*/ /*!50003 TRIGGER `t_reparateur_after_upd_tr` AFTER UPDATE ON `t_reparateur` FOR EACH ROW BEGIN
	IF NEW.`InitSatus`=0 THEN
    	DELETE FROM `t_numeroappel`
        WHERE `t_numeroappel`.`IDNumAppel`=NEW.`IDNumAppel`;
    END IF;
END */;;
