ectuee avec succes.','MESSAGE A L\'AGENT FORMEN OU LE SOCIOLOGUE(APPELANT) LORS D\'UNE INITIALISATION'),(10,'sofie_confirmation_cde','NOTIF_CDE_REP','${sofie_NUMERO_COMITE}','PROJET SOFIE: LA COMMANDE POUR LA REPARATION DE VOTRE FORAGE VIENT D\'ETRE RECEPTIONNE PAR LE REPARATEUR.LA DGEA VOUS REMERCIE.','MESSAGE AU COMITE EAU LORS D\'UNE PRISE DE COMMANDE D\'UN REPARATEUR'),(11,'sofie_confirmation_cde','NOTIF_CDE_REP','${CALLERID(Num)}','PROJET SOFIE: VOTRE SIGNALEMENT DE RECEPTION DE COMMANDE POUR L OUVRAGE:${sofie_CODE_FORAGE} A ETE ENREGISTRE.NUMERO-PANNE:${sofie_TICKET_PANNE}. LA DGEA VOUS REMERCIE.','MESSAGE AU REPARATEUR(APPELANT) LORS D\'UNE PRISE DE LA COMMANDE DU REPARATEUR'),(12,'sofie_confirmation_cde','NOTIF_CDE_REP','${sofie_NUMERO_AGENT}','PROJET SOFIE: UN SIGNALEMENT DE RECEPTION DE COMMANDE A ETE ENREGISTE POUR L OUVRAGE:${sofie_CODE_FORAGE}. NUMERO-PANNE:${sofie_TICKET_PANNE}.','MESSAGE A L\'AGENT FORMEN LORS D\'UNE PRISE DE LA COMMANDE DU REPARATEUR'),(13,'sofie_confirmation_cde','NOTIF_CDE_AGENT','${sofie_NUMERO_COMITE}','PROJET SOFIE: LA COMMANDE POUR LA REPARATION DE VOTRE FORAGE A ETE RECEPTIONNE. UN REPARATEUR A ETE MANDATE. LA DGEA VOUS REMERCIE.','MESSAGE AU COMITE EAU LORS D\'UNE PRISE DE LA COMMANDE  PAR UN AGENT FORMEN OU LE SOCIOLOGUE'),(14,'sofie_confirmation_cde','NOTIF_CDE_AGENT','${CALLERID(Num)}','PROJET SOFIE: VOTRE SIGNALEMENT DE RECEPTION DE COMMANDE POUR L OUVRAGE:${sofie_CODE_FORAGE} A ETE ENREGISTRE. NUMERO-PANNE:${sofie_TICKET_PANNE}. LA DGEA VOUS REMERCIE.','MESSAGE A AGENT FORMEN(APPELANT) LORS D\'UNE PRISE DE LA COMMANDE'),(15,'sofie_confirmation_cde','NOTIF_CDE_AGENT','${sofie_NUMERO_SOCIOLOGUE}','PROJET SOFIE: UNE PRISE EN CHARGE DE LA COMMANDE DE REPARATION DE L OUVRAGE:${sofie_CODE_FORAGE} VIENT D ETRE SIGNALEE. NUMERO-PANNE:${sofie_TICKET_PANNE}.','MESSAGE AU SOCIOLOGUE LORS D\'UNE PRISE DE LA COMMANDE  PAR UN AGENT FORMEN'),(16,'sofie_signaler_absence','NOTIF_ABSENCE','${CALLERID(Num)}','PROJET SOFIE: VOS NOTIFICATIONS SOFIE PAR SMS SERONT DESORMAIS TRANSFEREES VERS LE ${sofie_NUM_INTERIM}. LA DGEA VOUS REMERCIE.','MESSAGE RECU PAR L\'AGENT(APPELANT) QUI DESIR TRANSFERER SES SMS SOFIE VERS UN AUTRE AGENT INTERIMAIRE DURANT SON ABSENCE'),(17,'sofie_signaler_absence','NOTIF_ABSENCE','${sofie_NUM_INTERIM}','PROJET SOFIE: LE NUMERO ${CALLERID(Num)} VOUS A TRANSFERE SES NOTIFICATIONS SMS SOFIE. LA DGEA VOUS REMERCIE.','MESSAGE RECU PAR L\'AGENT INTERIMAIRE QUI ASSURERA L\'INTERIME D\'AGENT FORMEN ET RECEVRA DESORAIS LES SMS SOFIE DE CE DERNIER '),(18,'sofie_signaler_reprise','NOTIF_REPRISE','${CALLERID(Num)}','PROJET SOFIE: VOTRE NOTIFICATION DE REPRISE DE SERVICE A ETE ENREGISTRE, LA DGEA VOUS REMERCIE.','MESSAGE A RECU PAR L\'AGENT(APPELANT) QUI DESIR TRANSFERER SES SMS SOFIE VERS UN AUTRE AGENT INTERIMAIRE DURANT SON ABSENCE'),(19,'sofie_signaler_reprise','NOTIF_REPRISE','${sofie_NUM_INTERIM}','PROJET SOFIE: M.${sofie_NOM_AGENT} AU NUMERO ${CALLERID(Num)} A REPRIS LE SERVICE. LES SMS SOFIE LE CONCERNANT LUI SERONT A NOUVEAU TRANSFERES. LA DGEA VOUS REMERCIE.','MESSAGE A RECU PAR L\'AGENT QUI DESIR TRANSFERER SES SMS SOFIE VERS UN AUTRE AGENT INTERIMAIRE DURANT SON ABSENCE'),(20,'NO_CONTEXT','ALERT_HD_PRISE_CDE','N/A','PROJET SOFIE: ${sofie_INFOS_OUVRAGE} PRISE DE COMMANDE HORS DELAI!','MESSAGE ALERT PRISE DE CDE HORS DELAIS.${sofie_INFOS_OUVRAGE}:CONTIENT LES INFOS SUR L\' OUVRAGE CONCERNE.'),(21,'NO_CONTEXT','ALERT_HD_REPARATION','N/A','PROJET SOFIE: ${sofie_INFOS_OUVRAGE} HORS DELAI DE REPARATION!','MESSAGE ALERT HORS DELAIS DE REPARATION.${sofie_INFOS_OUVRAGE}:CONTIENT LES INFOS SUR L\' OUVRAGE CONCERNE.'),(22,'sofie_enreg_incident','NOTIF_NONREPARATION','${CALLERID(Num)}','PROJET SOFIE: LE FORAGE: ${sofie_CODE_FORAGE} NE PEUT ETRE REPARE POUR INDISPONIBILITE DE PIECES. LA DGEA VOUS REMERCIE.',''),(23,'sofie_enreg_incident','NOTIF_NONREPARATION','${sofie_NUMERO_REPARATEUR}','PROJET SOFIE: LE FORAGE: ${sofie_CODE_FORAGE} NE PEUT ETRE REPARE POUR INDISPONIBILITE DE PIECES. LA DGE