DELIMITER ;;
CREATE DEFINER=`sofie`@`%` FUNCTION `f_checkProfileInit`(
        _NUM_APPEL VARCHAR(20),
        _INIT_CODE VARCHAR(10)
    ) RETURNS tinyint(4)
    DETERMINISTIC
BEGIN

DECLARE _INIT_RESULT INTEGER(2);

	IF(SUBSTR(_INIT_CODE,1,1)=1) THEN
		SET _INIT_RESULT = (SELECT IF(f_getNumAppelByIDNumAppel(`t_comite`.`IDNumAppel`)=_NUM_APPEL,1,0) FROM `t_comite` WHERE `t_comite`.`CodeInitComite`=_INIT_CODE AND ISNULL(`t_comite`.`deleted_at`));
    END IF;  
    
    IF(SUBSTR(_INIT_CODE,1,1)=2) THEN
		SET _INIT_RESULT = (SELECT IF(f_getNumAppelByIDNumAppel(`t_reparateur`.`IDNumAppel`)=_NUM_APPEL,1,0) FROM `t_reparateur`  WHERE `t_reparateur`.`CodeInitRep`=_INIT_CODE AND ISNULL(`t_reparateur`.`deleted_at`));
    END IF; 
    
    IF(SUBSTR(_INIT_CODE,1,1)>=3) THEN
		SET _INIT_RESULT = (SELECT IF(f_getNumAppelByIDNumAppel(`t_agent`.`IDNumAppel`)=_NUM_APPEL,1,0) FROM `t_agent` WHERE `t_agent`.`CodeInitAgent`=_INIT_CODE AND ISNULL(`t_agent`.`deleted_at`));
    END IF;

  RETURN (_INIT_RESULT);
END ;;
DELIMITER ;
