CREATE DEFINER=`root`@`%` FUNCTION `f_getInfosOuvrageByCodeOuvrage`(
        _CODE_OUVRAGE VARCHAR(5)
    ) RETURNS varchar(255) CHARSET latin1
BEGIN

  RETURN (SELECT CONCAT(r.`NomRegion`,'/',l.`NomLocalite`,'/',c.`NomComite`,' OUVRAGE:',o.`CodeOuvrage`)AS INFOS_OUVRAGE
FROM `t_ouvrage` o,`t_region` r,`t_localite` l,`t_comite` c
WHERE
o.`IDRegion`=r.`IDRegion` AND
o.`IDLocalite`=l.`IDLocalite` AND
o.`IDComite`=c.`IDComite` AND
o.`CodeOuvrage`=_CODE_OUVRAGE);
END ;;
