CREATE DEFINER=`sofie`@`%` PROCEDURE `P_INSERT_NOTIFICATION`(
        IN _MOTIFNOTIF TINYINT(2),
        IN _IDPANNE INTEGER(11),
        IN _IDNUMAPPEL INTEGER(11)
    )
BEGIN
	DECLARE EXIT HANDLER FOR SQLEXCEPTION ROLLBACK;
	DECLARE EXIT HANDLER FOR SQLWARNING ROLLBACK;	
	START TRANSACTION;

	IF (ISNULL(_IDPANNE)OR(_IDPANNE=0)) THEN 
    	SET _IDPANNE = (SELECT MAX(`t_panne`.`IDPanne`) FROM `t_panne` WHERE `t_panne`.`IDOuvrage`=`f_getIDOuvrageByNumAppel`(f_getNumAppelByIDNumAppel(_IDNUMAPPEL)));
	END IF;
    
	INSERT INTO `t_notification` (DateHeureNotif,MotifNotif,IDPanne,IDNumAppel)VALUES(NOW(),_MOTIFNOTIF,_IDPANNE,_IDNUMAPPEL);  
    COMMIT;
    
END ;;
