        IN _PHONE_AGENT VARCHAR(12),
        OUT _NOMAGENT VARCHAR(100)
    )
BEGIN

 SELECT CONCAT(`t_agent`.`NomAgent`,' ',`t_agent`.`PrenomsAgent`) AS NOMREP INTO _NOMAGENT
    FROM `t_agent`
    WHERE 
