CREATE DEFINER=`sofie`@`%` PROCEDURE `P_SELECT_INFOS_OUVRAGE_BY_NUMAPPEL_COMITE`(
        IN _NUMAPPEL VARCHAR(12),
        OUT _CODEOUVRAGE VARCHAR(10),
        OUT _IDREGION INTEGER(10),
        OUT _NOMLOCALITE VARCHAR(50),
        OUT _NOMCOMITE VARCHAR(100),
        OUT _NUMAPPEL_COMITE VARCHAR(12),
        OUT _NUMAPPEL_REP VARCHAR(12),
        OUT _NUMAGENT_FORMA VARCHAR(12),
        OUT _NUMAGENT_SOCIOLOGUE VARCHAR(12),
        OUT _NUM_DR VARCHAR(12),
        OUT _NOMREP VARCHAR(100),
        OUT _NOMAGENT_FORMA VARCHAR(100),
        OUT _NOMAGENT_SOCIOLOGUE VARCHAR(100),
        OUT _NOM_DR VARCHAR(100),
        OUT _STATUTOUVRAGE TINYINT(2),
        OUT _VALIDATED TINYINT(2),
        OUT _TICKET_PANNE VARCHAR(12)
    )
    DETERMINISTIC
    SQL SECURITY INVOKER
BEGIN

DECLARE IDREGION INTEGER(10);
DECLARE IDLOCALITE INTEGER(10);
DECLARE IDREPARATEUR INTEGER(10);

DECLARE IDAGENT_FORMA INTEGER(10);
DECLARE IDSOCIOLOGUE INTEGER(10);
DECLARE IDDR INTEGER(10);
DECLARE IDOUVRAGE INTEGER(11);
	
	SET _NUMAPPEL_COMITE=_NUMAPPEL;
    
	SELECT `t_ouvrage`.`CodeOuvrage`,`t_ouvrage`.`IDOuvrage`,`t_ouvrage`.`Statut`,`t_ouvrage`.`validated`,`t_ouvrage`.`IDLocalite`
    INTO _CODEOUVRAGE,IDOUVRAGE,_STATUTOUVRAGE,_VALIDATED,IDLOCALITE
    FROM `t_ouvrage`
    WHERE `t_ouvrage`.`IDComite`=`f_getIDComiteByIDNumAppel`(f_getIDNumappelByNumAppel(_NUMAPPEL)) AND ISNULL(`t_ouvrage`.`deleted_at`);
   
    SELECT `t_localite`.`IDAgentForma`,`t_localite`.`IDReparateur` 
    INTO IDAGENT_FORMA,IDREPARATEUR
    FROM `t_localite`
    WHERE `t_localite`.`IDLocalite`=IDLOCALITE;
    
    SELECT `t_comite`.`NomComite`
    INTO _NOMCOMITE
    FROM `t_comite`
    WHERE 
    `t_comite`.`IDComite`=`f_getIDComiteByIDNumAppel`(f_getIDNumappelByNumAppel(_NUMAPPEL));
    
    SELECT CONCAT(`t_reparateur`.`NomRep`,' ',`t_reparateur`.`PrenomsRep`) AS NOMREP ,`t_numeroappel`.`NumAppel` 
    INTO _NOMREP,_NUMAPPEL_REP
    FROM `t_reparateur`,`t_numeroappel`
    WHERE 
    `t_reparateur`.`IDNumAppel` = `t_numeroappel`.`IDNumAppel` AND
    `t_reparateur`.`IDReparateur` = IDREPARATEUR;
    
    SELECT `t_region`.`IDRegion`, CONCAT(`t_region`.`NomRegion`,'/',`t_localite`.`NomLocalite`) AS NOMLOCALITE 
    INTO _IDREGION,_NOMLOCALITE
    FROM `t_region`,`t_localite`
    WHERE 
    `t_region`.`IDRegion`=`t_localite`.`IDRegion`
    AND `t_localite`.`IDLocalite`=IDLOCALITE
    ;
    
    SELECT CONCAT(`t_agent`.`NomAgent`,' ',`t_agent`.`PrenomsAgent`)AS NOMAGENT_FORMA, `t_numeroappel`.`NumAppel` 
    INTO _NOMAGENT_FORMA,_NUMAGENT_FORMA
    FROM `t_agent`,t_numeroappel 
    WHERE 
    `t_agent`.`IDNumAppelNotification`=`t_numeroappel`.`IDNumAppel`
    AND `t_agent`.`Qualification`=3
    AND `t_agent`.`IDRegion`=_IDREGION
    AND `t_agent`.`IDAgent`=IDAGENT_FORMA;
    
    SELECT CONCAT(`t_agent`.`NomAgent`,' ',`t_agent`.`PrenomsAgent`)AS NOMAGENT_SOCIOLOGUE, `t_numeroappel`.`NumAppel` 
    INTO _NOMAGENT_SOCIOLOGUE,_NUMAGENT_SOCIOLOGUE
    FROM `t_agent`,`t_region`,t_numeroappel 
    WHERE 
    `t_agent`.`IDNumAppelNotification`=`t_numeroappel`.`IDNumAppel`
    AND `t_agent`.`IDRegion`=`t_region`.`IDRegion`
    AND `t_agent`.`IDAgent`=`t_region`.`IDSociologue`
    AND `t_agent`.`IDRegion`=_IDREGION;
    
    SELECT CONCAT(`t_agent`.`NomAgent`,' ',`t_agent`.`PrenomsAgent`)AS NOM_DR, `t_numeroappel`.`NumAppel` 
    INTO _NOM_DR,_NUM_DR
    FROM `t_agent`,`t_region`,t_numeroappel 
    WHERE 
    `t_agent`.`IDNumAppelNotification`=`t_numeroappel`.`IDNumAppel`
    AND `t_agent`.`IDRegion`=`t_region`.`IDRegion`
    AND `t_agent`.`IDAgent`=`t_region`.`IDDR`
    AND `t_agent`.`IDRegion`=_IDREGION;
    
    SELECT `f_getPanneTicketByIDOuvrage`(IDOUVRAGE) INTO _TICKET_PANNE;
    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `P_SELECT_INFOS_OUVRAGE_BY_NUMPANNE` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
